,{"schemaVersion":"2.0","id":"mbo-par-6-abs-1-satz-2","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 1 Satz 2","elements":[{"elementId":"doc/teil-2/par-6/abs-1","sentenceId":"doc/teil-2/par-6/abs-1/satz-2","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"§ 6 Abs. 1 Satz 1 gilt entsprechend für andere Anlagen, von denen Wirkungen wie von Gebäuden ausgehen, gegenüber Gebäuden und Grundstücksgrenzen."},"applicability":{"targets":[{"entity":"andere Anlage","entityType":"other_structure","description":"Anlagen, von denen Wirkungen wie von Gebäuden ausgehen"}]},"requirements":[{"kind":"boolean","fact":"setback_area.kept_free_from_above_ground_buildings","value":true,"description":"Abstandsflächen vor anderen Anlagen mit gebäudeähnlicher Wirkung müssen gegenüber Gebäuden und Grundstücksgrenzen freigehalten werden."}],"exceptions":[{"kind":"exception","effect":"disapplies_rule","description":"Satz 2 gilt nicht für Antennen im Außenbereich einschließlich der Masten mit einer maximalen Breite des Mastes von 1,50 m und einer Gesamthöhe von nicht mehr als 50 m gegenüber anderen Grundstücken im Außenbereich.","condition":{"kind":"all","conditions":[{"kind":"comparison","fact":"structure.type","operator":"==","value":"antenna_including_mast","valueType":"string"},{"kind":"comparison","fact":"structure.location","operator":"==","value":"aussenbereich","valueType":"string"},{"kind":"comparison","fact":"structure.mast_width","operator":"<=","value":1.5,"valueType":"number","unit":"m"},{"kind":"comparison","fact":"structure.total_height","operator":"<=","value":50,"valueType":"number","unit":"m"},{"kind":"comparison","fact":"neighbouring_plot.location","operator":"==","value":"aussenbereich","valueType":"string"}]}}],"references":[{"citation":"§ 6 Abs. 1 Satz 1","elementId":"doc/teil-2/par-6/abs-1","resolution":"resolved","relationship":"depends_on"}],"review":{"status":"draft"